"""Password hashing tests.

These guard against the passlib/bcrypt incompatibility that made login return
500 on fresh deployments (passlib 1.7.4 + bcrypt >= 4.1).
"""

import pytest

from app.core.security import hash_password, verify_password

# Hash generated by bcrypt 4.0; it must keep validating with newer bcrypt
# releases so existing users are not locked out after an upgrade.
LEGACY_HASH = "$2b$12$Spj38O5AfFgr65KlgL0HXue0Hx/z8d4vKT0d0/wqpUjV75V2NEDpy"
MIN_BCRYPT_ROUNDS = 12


def test_hash_and_verify_round_trip() -> None:
    hashed = hash_password("pass1234")

    assert hashed.startswith("$2")
    assert hashed != "pass1234"
    assert verify_password("pass1234", hashed) is True
    assert verify_password("wrong-password", hashed) is False


def test_verifies_hashes_created_by_older_bcrypt() -> None:
    assert verify_password("pass1234", LEGACY_HASH) is True


def test_long_password_does_not_raise() -> None:
    password = "á" * 200  # 400 UTF-8 bytes, well over bcrypt's 72-byte limit

    hashed = hash_password(password)

    assert verify_password(password, hashed) is True
    assert verify_password(password[:36], hashed) is True  # same first 72 bytes


@pytest.mark.parametrize("malformed", ["", "not-a-hash", "$2b$12$too-short"])
def test_malformed_hash_returns_false(malformed: str) -> None:
    assert verify_password("pass1234", malformed) is False


def test_new_hashes_use_a_reasonable_bcrypt_cost() -> None:
    hashed = hash_password("pass1234")
    rounds = int(hashed.split("$")[2])

    assert rounds >= MIN_BCRYPT_ROUNDS
